svg.script:
window.onload = function() {
  const elements = document.querySelectorAll('path, text');
  const originals = new Map();
  elements.forEach(el => {
    originals.set(el, el.getAttribute('transform') || '');
  });

  function explode() {
    elements.forEach(el => {
      const x = (Math.random() - 0.5) * 800;
      const y = (Math.random() - 0.5) * 800;
      const rot = (Math.random() - 0.5) * 120;
      const scale = 0.7 + Math.random() * 0.6;
      el.style.transition = 'transform 0.9s cubic-bezier(0.25, 0.1, 0.25, 1)';
      el.setAttribute('transform', `translate(${x} ${y}) rotate(${rot}) scale(${scale})`);
    });

    setTimeout(() => {
      elements.forEach(el => {
        el.style.transition = 'transform 0.5s ease-in';
        const orig = originals.get(el);
        if (orig) {
          el.setAttribute('transform', orig);
        } else {
          el.removeAttribute('transform');
        }
      });
    }, 1100);
  }

  // Start the cycle every 5 seconds
  setInterval(explode, 5000);

  // Optional: trigger first explosion after a short delay to show the intact image first
  setTimeout(explode, 2000);
};
